source = source_path.read_text()
match = re.search(r"^static uint8_t smc_message\([^\n]*\)\n\{.*?^\}", source, re.M | re.S)
if not match:
    raise SystemExit("NO-GO: exact smc_message() function not present in " + str(source_path))

